const RATE_LIMIT_WINDOW_MS = 60 * 1000;
const RATE_LIMIT_MAX = 3;

// Use globalThis for state that persists across hook invocations within the
// PocketBase JSVM (per-file top-level `const`/`let` are scoped to the bundled
// module and are not reliably shared across calls).
if (typeof globalThis.__signupRateLimitStore === "undefined") {
    globalThis.__signupRateLimitStore = {};
}
const rateLimitStore = globalThis.__signupRateLimitStore;

onRecordCreateRequest((e) => {
    if (!e.collection || e.collection.name !== "users") {
        return;
    }

    const ip = e.realIP();
    const now = Date.now();

    if (!rateLimitStore[ip]) {
        rateLimitStore[ip] = [];
    }
    const timestamps = rateLimitStore[ip];

    // Drop entries that fall outside the rolling 60s window.
    const cutoff = now - RATE_LIMIT_WINDOW_MS;
    while (timestamps.length > 0 && timestamps[0] <= cutoff) {
        timestamps.shift();
    }

    if (timestamps.length >= RATE_LIMIT_MAX) {
        const oldest = timestamps[0];
        const retryAfterMs = (oldest + RATE_LIMIT_WINDOW_MS) - now;
        let retryAfterSec = Math.ceil(retryAfterMs / 1000);
        if (retryAfterSec < 1) {
            retryAfterSec = 1;
        }

        // Set the Retry-After header before writing the response body.
        try {
            e.response.header().set("Retry-After", String(retryAfterSec));
        } catch (_) {}

        // 429 response with `retryAfter` at the top level of the JSON body.
        e.json(429, {
            status: 429,
            message: "Too many signup attempts. Please try again later.",
            retryAfter: retryAfterSec,
        });

        // Stop processing further hooks/handlers.
        throw new ApiError(429, "stop", {});
    }

    timestamps.push(now);
}, "users");
